-- Work experience entries, linked to companies and project ids

create table "public"."work" (
  "id" bigint primary key generated by default as identity,
  "position" varchar,
  "start" date,
  "end" date,
  "description" text,
  "user" uuid,
  "order" smallint,
  "is_active" boolean not null default true,
  "company_id" bigint,
  "project_ids" integer[]
);

alter table "public"."work" add constraint "work_company_id_fkey" foreign key ("company_id") references "public"."companies" (id) on update cascade on delete cascade;
alter table "public"."work" add constraint "work_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."work" enable row level security;
create policy "Enable read access for all users" on "public"."work" for select using (true);

grant all on "public"."work" to postgres, anon, authenticated, service_role;
